266	     * Validates the given {@link InputTextView}. If the input is invalid a Toast will be displayed
267	     * to the user and the previously entered character will be removed.
268	     *
269	     * @param input The {@link InputTextView} to validate.
270	     * @return The text of the input as a double.
271	     */
272	    private double validateCoordinateInput(InputTextView input) {
273	        String inputText = input.getInputText();
274	
275	        // do not validate if the user is entering a negative coordinate
276	        if (inputText.length() == 1 && inputText.charAt(0) == '-')
277	            return -1;
278	
279	        try {
280	            inputText = inputText.replace(',', '.'); // some countries/keyboard use ',' in place of '.'
281	            return (double) Utils.asFloat(inputText, 0);
282	        } catch (NumberFormatException e) {
283	            e.printStackTrace();
284	            Utils.showToast(getContext(), R.string.msg_invalid_coordinate);
285	            input.pressBackspace();
286	        }
287	
288	        return -1;
289	    }
